with valid as (select *, case when budget >= 3061000 then 'High' when budget >= 1207000 then 'Medium' else 'Low' end as budget_tier, coalesce(dept_name, 'UNKNOWN') as dept_name_filled from departments where budget < 1861000) select s.id, s.budget, latest.employee_salary from valid s join lateral (select c.salary as employee_salary from employees c where c.dept_id = s.id order by c.hire_date desc, c.id desc limit 1) latest on true
